 const pref={get:k=>{try{return localStorage.getItem(`rise-gym-${k}-${owner}`);}catch{return null;}},set:(k,v)=>{try{v===null?localStorage.removeItem(`rise-gym-${k}-${owner}`):localStorage.setItem(`rise-gym-${k}-${owner}`,v);}catch{}}};
 const deloadOn=()=>pref.get('deload')===mondayOf(local());
 const compoundNames=()=>plan.flatMap(d=>d[2].filter(e=>e[5]).map(e=>e[0]));
 let lastPhotoDate,photoChecked=false;
 async function checkPhotos(){if(photoChecked||!owner)return;photoChecked=true;try{const list=await listProgressPhotos(db,owner);lastPhotoDate=list[0]?.date||null;}catch{lastPhotoDate=undefined;}if(view==='train'&&!active)render();}
 function remindersHtml(){const today=local(),out=[];const adv=deloadAdvice(rows,compoundNames(),today);
  if(deloadOn())out.push(`<div class="card gym-remind gym-remind-deload"><b>Semana de descarga activa</b><p class="small">Las sesiones que empieces esta semana llevan la mitad de series y un 10 % menos de carga. Termina el lunes.</p><button type="button" class="secondary" data-deload="off">Desactivar</button></div>`);
  else if(adv)out.push(`<div class="card gym-remind gym-remind-deload"><b>Te toca una semana de descarga</b><p class="small">Porque ${esc(adv.reason)}. Una semana más suave ayuda a recuperar y volver a progresar.</p><button type="button" class="primary" data-deload="on">Activar descarga esta semana</button></div>`);
  if(lastPhotoDate!==undefined&&!(pref.get('photo-snooze')>=today)){const r=photoReminder(lastPhotoDate,today);if(r.due)out.push(`<div class="card gym-remind"><b>${r.days===null?'Haz tu primera foto de progreso':`Toca foto de progreso · última hace ${r.days} días`}</b><p class="small">Cada 4 semanas, con la misma luz y pose, para comparar de verdad.</p><div class="actions"><button type="button" class="primary" data-go-photos>Hacer foto</button><button type="button" class="secondary" data-photo-snooze>Ahora no</button></div></div>`);}
  return out.join('');}
 function balanceHtml(){const muscles=[...new Set(plan.flatMap(d=>d[2].map(e=>e[4])))],b=muscleBalance(rows,local(),muscles);const [lo,hi]=WEEKLY_RANGE,max=Math.max(hi+4,...b.map(x=>x.sets));
  return `<div class="card gym-balance"><h3>Series por músculo · esta semana</h3><p class="small">Rango orientativo ${lo}–${hi} series semanales por músculo. Entre paréntesis, la semana pasada.</p>${b.map(x=>`<div class="gym-balance-row gym-balance-${x.state}"><span>${esc(x.muscle)}</span><div class="gym-balance-track" aria-hidden="true"><i class="gym-balance-band" style="left:${lo/max*100}%;width:${(hi-lo)/max*100}%"></i><i class="gym-balance-bar" style="width:${Math.min(100,x.sets/max*100)}%"></i></div><b>${x.sets}</b><span class="small">(${x.last})</span></div>`).join('')}</div>`;}
 // Aviso breve (récord personal, etc.) fuera del contenido para sobrevivir a los re-renderizados.
